import { calculateProtocol, calculateDDP, suggestDDP, validateDistribution, PROTOCOL_DEFAULTS, PROTOCOL_FOODS, PROTOCOL_SOURCES } from './protocol.js';
import { loadPatients, savePatients, exportBackup, parseBackup } from './storage.js';
import { $, esc, num, initials, iso, shortDate, icon, plateArt } from './ui.js';

const clone = value => structuredClone(value);
const defaultMeals = () => [
  {id:'early',label:'Early morning',time:'6:30 AM',note:''},
  {id:'breakfast',label:'Breakfast',time:'8:00 AM',note:''},
  {id:'midmorning',label:'Mid-morning',time:'11:00 AM',note:''},
  {id:'lunch',label:'Lunch',time:'1:00 PM',note:''},
  {id:'evening',label:'Evening',time:'4:30 PM',note:''},
  {id:'dinner',label:'Dinner',time:'7:30 PM',note:''}
];
const newProtocol = value => {
 const legacyManual= value?.weightMode===undefined&&Number.isFinite(value?.calculationWeight);
 return {...clone(PROTOCOL_DEFAULTS),matchMode:'allowances',fiberTarget:null,...value,weightMode:value?.weightMode??(legacyManual?'custom':'recommended'),customWeight:value?.customWeight??(legacyManual?value.calculationWeight:null),calculationWeight:null,minorAllocations:{...clone(PROTOCOL_DEFAULTS.minorAllocations),...value?.minorAllocations},tolerances:{energy:100,carbs:25,protein:10,fat:5,...value?.tolerances}};
};
const normalize = p => ({age:null,sex:'female',height:null,weight:null,activity:'moderate',pregnant:false,lactating:false,biochem:{},notes:'',...p,protocol:newProtocol(p.protocol),ddp:p.ddp||{},distribution:p.distribution||{},protocolMeals:p.protocolMeals||defaultMeals(),protocolHistory:p.protocolHistory||[]});
let demo = normalize({id:'demo',name:'Ananya Rao',age:38,sex:'female',height:162,weight:68,activity:'moderate',demo:true,protocol:{weightMode:'recommended'},createdAt:iso(),updatedAt:iso()});
let patients=[], selectedId='demo', route='planner',step=0,labsOpen=false,query='',storageBlocked='',saveError='',installPrompt=null,swReady=false,pendingImport=null;
try{patients=loadPatients().map(normalize);selectedId=patients.find(p=>!p.archivedAt)?.id||'demo';}catch(e){storageBlocked=e.message;}
const activePatients=()=>patients.filter(p=>!p.archivedAt);
const current=()=>selectedId==='demo'?demo:patients.find(p=>p.id===selectedId)||demo;
const assessment=()=>calculateProtocol(current(),current().protocol);
const targetValues=(a=assessment())=>({energy:a.energy?.ter,carbs:a.macros?.targetGrams?.carbs,protein:a.macros?.targetGrams?.protein,fat:a.macros?.targetGrams?.fat});
const ddpResult=()=>calculateDDP(targetValues(),current().ddp,{tolerances:current().protocol.tolerances,fiberTarget:current().protocol.fiberTarget});
const distributionResult=()=>validateDistribution(current().ddp,current().protocolMeals.map(m=>m.id),current().distribution);
const foods=()=>Array.isArray(PROTOCOL_FOODS)?PROTOCOL_FOODS:Object.values(PROTOCOL_FOODS);
const foodById=id=>foods().find(f=>f.id===id);
const steps=['Assessment','Targets & CHO','DDP matrix','Meal division','Review'];
const nutrients=[['energy','Energy','kcal'],['carbs','Carbohydrate','g'],['protein','Protein','g'],['fat','Fat','g']];
const minorGroups=[['milk','Milk & curd'],['glv','Green leafy vegetables'],['otherVeg','Other vegetables'],['roots','Roots & tubers'],['fruit','Fruits'],['sugar','Sugars & jaggery']];
const rawMeal=id=>id==='cereals'||id==='pulses';
const fieldUnit=f=>f.id==='milk'?'ml':'g';
const labFields=[['fastingGlucose','Fasting glucose','mg/dL'],['hba1c','HbA1c','%'],['hemoglobin','Haemoglobin','g/dL'],['creatinine','Creatinine','mg/dL'],['totalCholesterol','Total cholesterol','mg/dL'],['triglycerides','Triglycerides','mg/dL'],['hdl','HDL cholesterol','mg/dL'],['ldl','LDL cholesterol','mg/dL'],['uricAcid','Uric acid','mg/dL'],['vitaminD','25-OH vitamin D','ng/mL']];
const factorFor=activity=>activity==='sedentary'?25:activity==='heavy'?35:30;
const minorSum=()=>minorGroups.reduce((sum,[id])=>sum+(Number(current().protocol.minorAllocations[id])||0),0);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(){if(current().demo)return true;if(storageBlocked){toast(storageBlocked);return false;}try{savePatients(patients);saveError='';updateSaved();return true;}catch(e){saveError=e.message;updateSaved();toast(e.message);return false;}}
function updateSaved(){const el=$('#save-status');if(el)el.innerHTML=`${icon(saveError?'info':'check')} ${esc(saveError?'Not saved — export a backup':current().demo?'Example · not saved':'Saved on this device')}`;}
function changed(){current().updatedAt=iso();current().protocolReviewedAt=null;current().protocolVersion=1;persist();updateDerived();const badge=$('.patient-banner .badge');if(badge)badge.textContent=current().demo?'Example · not saved':'Draft plan';}
function navigate(next,nextStep=step){route=next;step=nextStep;$('#dialog').close();render();window.scrollTo({top:0,behavior:'instant'});}
function syncMenu(){const side=$('.sidebar');if(side)side.inert=matchMedia('(max-width:720px)').matches&&!side.classList.contains('open');}
function render(){document.title=`${route==='planner'?'Clinical diet protocol':route==='patients'?'Patients':route==='reference'?'Protocol reference':'Device & data'} · Nourish`;$('#app').innerHTML=shell();syncMenu();updateSaved();}
function heading(title,description,action=true){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action?`<button class="btn primary" data-action="add">${icon('plus')} New patient</button>`:''}</div>`;}
function shell(){return `<div class="shell"><div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#" data-action="home"><div class="brand-mark">${icon('leaf')}</div><div><div class="brand-name">nourish<span>.</span></div><small>Clinical nutrition workspace</small></div></a><div class="nav-label">WORKSPACE</div><nav><button class="nav-btn ${route==='patients'?'active':''}" data-route="patients">${icon('people')}Patients <span class="nav-count">${activePatients().length}</span></button><button class="nav-btn ${route==='planner'?'active':''}" data-route="planner">${icon('plan')}Diet protocol</button><button class="nav-btn ${route==='reference'?'active':''}" data-route="reference">${icon('book')}Protocol reference</button><button class="nav-btn ${route==='settings'?'active':''}" data-route="settings">${icon('settings')}Device & data</button></nav><div class="side-patients"><div class="nav-label">RECENT PATIENTS</div>${activePatients().slice().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,6).map(p=>`<button class="patient-nav ${selectedId===p.id?'current':''}" data-patient="${esc(p.id)}"><span class="avatar">${esc(initials(p.name))}</span>${esc(p.name)}</button>`).join('')}<button class="patient-nav" data-action="demo"><span class="avatar">${icon('leaf')}</span>Example workspace</button><button class="patient-nav" data-action="add">${icon('plus')}Add a patient</button></div><div class="side-bottom"><div class="privacy-card"><div class="row">${icon('shield')}<strong>Private by design</strong></div><p>Patient records and calculation history stay in this browser.</p></div><div class="doctor row"><span class="avatar">${icon('user')}</span><div><strong>Doctor’s workspace</strong><p>Clinical protocol · Local only</p></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-root">Workspace</span>${icon('right')}<strong>${{planner:'Clinical diet protocol',patients:'Patients',reference:'Protocol reference',settings:'Device & data'}[route]}</strong></div></div><div class="top-actions"><span class="local-status" id="network-status"><i class="dot"></i>${swReady?'Offline ready':'Local workspace'}</span><button class="btn small-btn" data-action="install">${icon('download')}Install app</button></div></header><main class="workspace" id="main" tabindex="-1">${storageBlocked?`<div class="alert error">${esc(storageBlocked)} Saving is disabled to protect stored records.</div>`:''}<div class="page-view">${route==='planner'?planner():route==='patients'?patientList():route==='reference'?referencePage():settingsPage()}</div><footer class="footer"><span>${icon('leaf')}Personally assessed. Precisely accounted for.</span><span>Supplied clinical protocol · Clinician review required</span></footer></main></div></div>`;}
function planner(){const p=current();return `${heading('Clinical diet protocol','From patient measurements to a reconciled daily diet prescription.')}<section class="patient-banner" aria-label="Selected patient"><div class="row"><div class="avatar">${esc(initials(p.name))}</div><div><div class="row wrap"><h2>${esc(p.name)}</h2><span class="badge ${p.demo?'demo':''}">${p.demo?'Example · not saved':p.protocolReviewedAt?'Reviewed plan':'Draft plan'}</span></div><p>${p.age??'—'} years · ${p.sex==='male'?'Male':'Female'} · ${esc(p.activity)} activity</p></div></div><div class="row patient-details"><div class="patient-detail">Patient ID<b>${p.demo?'EXAMPLE':esc(p.id.slice(0,8).toUpperCase())}</b></div><div class="patient-detail">Updated<b>${shortDate(p.updatedAt)}</b></div></div><button class="btn small-btn" data-action="${p.demo?'add':'edit-patient'}">${icon(p.demo?'plus':'edit')}${p.demo?'Create patient':'Edit patient'}</button></section>${p.settings&&!p.protocolVersion?'<div class="alert info">This record has a plan from the earlier calculation model. Its settings and review history are retained in backups. Select the calculation weight and build a new clinical-protocol plan before review.</div>':''}${p.referenceExample?'<div class="alert info">Supplied reference example loaded as written. Red checks expose inconsistencies between its stated targets, DDP weights and meal portions. This example is not saved as a patient.</div>':''}<nav class="stepper protocol-steps" aria-label="Plan steps">${steps.map((label,i)=>`<button class="step ${step===i?'active':step>i?'completed':''}" data-step="${i}" ${step===i?'aria-current="step"':''}><span class="step-number">${step>i?'✓':i+1}</span>${label}</button>`).join('')}</nav><div id="metrics">${metrics()}</div><div id="validation">${validation()}</div>${[assessmentPage,targetsPage,ddpPage,mealPage,reviewPage][step]()}`;}
function metrics(){const a=assessment(),p=current();return `<section class="metrics"><div class="metric"><div class="metric-header"><div><div class="metric-label">BODY MASS INDEX</div><div class="metric-number">${num(a.anthropometrics?.bmi,1)}<span class="metric-unit">kg/m²</span></div></div><div class="metric-icon">${icon('scale')}</div></div><div class="metric-foot"><span class="badge">${esc(a.anthropometrics?.asianIndianCategory||'Awaiting measurements')}</span><p style="margin-top:5px">Asian Indian action thresholds</p></div></div><div class="metric energy"><div class="metric-header"><div><div class="metric-label">TOTAL ENERGY REQUIREMENT</div><div class="metric-number">${num(a.energy?.ter)}<span class="metric-unit">kcal / day</span></div></div><div class="metric-icon">${icon('fire')}</div></div><div class="metric-foot">${num(a.anthropometrics?.calculationWeightKg,1)} kg × ${num(p.protocol.activityFactor)} kcal/kg</div></div><div class="metric protein"><div class="metric-header"><div><div class="metric-label">PROTEIN TARGET</div><div class="metric-number">${num(a.macros?.targetGrams?.protein,1)}<span class="metric-unit">g / day</span></div></div><div class="metric-icon">${icon('protein')}</div></div><div class="metric-foot">${num(p.protocol.protein)}% of TER · ${p.protocol.roundMacroTargets?'whole-gram target':'unrounded target'}</div></div></section>`;}
function validation(){const a=assessment();return [...(a.errors||[]).map(e=>`<div class="alert error">${esc(e)}</div>`),...(a.warnings||[]).map(e=>`<div class="alert">${esc(e)}</div>`)].join('');}
function field(label,path,value,unit='',options={}){return `<div class="field ${options.full?'full':''}"><label for="${path}">${label}</label><div class="input-wrap"><input id="${path}" data-field="${path}" type="${options.type||'number'}" value="${esc(value??'')}" ${options.type==='text'?'maxlength="120"':'inputmode="decimal" step="any" min="'+(options.min??0)+'"'} ${options.max!==undefined?'max="'+options.max+'"':''} placeholder="${esc(options.placeholder||'—')}">${unit?`<span class="input-unit">${unit}</span>`:''}</div>${options.hint?`<p class="field-hint">${options.hint}</p>`:''}</div>`;}
function weightChoice(){const p=current(),a=assessment(),mode=p.protocol.weightMode;const options=[['recommended','Recommended by BMI'],['actual','Actual body weight'],['ibw','Ideal body weight (IBW)'],['abw','Adjusted body weight (ABW)'],['custom','Custom weight']];return `<div class="field"><label for="weight-mode">Weight used for TER</label><select id="weight-mode" data-field="protocol.weightMode">${options.map(([id,label])=>`<option value="${id}" ${mode===id?'selected':''}>${id==='recommended'?(a.anthropometrics?.bmi>=23?'Recommended · ABW':'Recommended · actual weight'):label}</option>`).join('')}</select><p class="field-hint">${a.anthropometrics?.bmi>=23?'BMI ≥23: the default is ABW rounded to the nearest kg.':'BMI <23: the default is actual weight.'} Select IBW, ABW or enter a custom weight whenever clinically appropriate.</p></div><div class="weight-choice-cards"><div><span>Actual</span><strong>${num(a.anthropometrics?.actualWeightKg,2)} kg</strong></div><div><span>IBW · BMI 22.5</span><strong>${num(a.anthropometrics?.idealBodyWeightKg,2)} kg</strong></div><div><span>ABW · 25% correction</span><strong>${num(a.anthropometrics?.adjustedBodyWeightKg,2)} kg</strong><small>TER weight if selected: ${num(a.anthropometrics?.adjustedBodyWeightKg===null?null:Math.round(a.anthropometrics.adjustedBodyWeightKg),0)} kg</small></div></div>${mode==='custom'?`<div style="margin-top:16px">${field('Custom calculation weight','protocol.customWeight',p.protocol.customWeight,'kg',{min:1,max:500,hint:'Enter the clinician-selected weight used for TER.'})}</div>`:''}<p class="field-hint weight-formula">IBW = height (m)² × 22.5 · ABW = IBW + 0.25 × (actual weight − IBW). The reference case rounds its calculated ABW to 59 kg for TER.</p>`;}
function sourceNote(){return `<div class="source-note">${icon('book')}<span>Calculation rules and exchange constants follow the supplied developer specification. <button class="btn text" data-route="reference">View protocol and reference discrepancies</button></span></div>`;}
function assessmentPage(){const p=current();return `<div class="content-grid"><div class="stack"><section class="card card-pad"><div class="card-head"><div><h2>Patient measurements</h2><p>Actual weight determines BMI. Calculation weight determines TER.</p></div>${icon('user')}</div><div class="form-grid">${field('Height','height',p.height,'cm',{min:80,max:250})}${field('Actual body weight','weight',p.weight,'kg',{min:20,max:350})}${field('Age','age',p.age,'years',{max:120})}<div class="field"><label for="sex">Sex</label><select id="sex" data-field="sex"><option value="female" ${p.sex==='female'?'selected':''}>Female</option><option value="male" ${p.sex==='male'?'selected':''}>Male</option></select></div></div><hr class="section-divider"><div id="weight-choice">${weightChoice()}</div><hr class="section-divider"><label class="field-label">Habitual activity level</label><div class="activity-options">${[['sedentary','chair','Sedentary','25 kcal/kg'],['moderate','walk','Moderate','30 kcal/kg'],['heavy','run','Heavy','35–40 kcal/kg']].map(([value,i,label,detail])=>`<button class="activity-btn ${p.activity===value?'active':''}" data-activity="${value}" aria-pressed="${p.activity===value}">${icon(i)}<strong>${label}</strong><small>${detail}</small></button>`).join('')}</div>${p.activity==='heavy'?`<div style="margin-top:18px">${field('Heavy activity factor','protocol.activityFactor',p.protocol.activityFactor,'kcal/kg',{min:35,max:40})}</div>`:''}<div class="row wrap" style="margin-top:20px"><label class="toggle-check"><input type="checkbox" data-field="pregnant" ${p.pregnant?'checked':''}>Pregnancy</label><label class="toggle-check"><input type="checkbox" data-field="lactating" ${p.lactating?'checked':''}>Lactation</label></div><div class="form-footer"><span class="row small muted" id="save-status"></span><button class="btn primary" data-step="1">Set targets ${icon('arrow')}</button></div></section><section class="card card-pad"><button class="biochem-toggle" data-action="labs" aria-expanded="${labsOpen}"><div><div class="card-title-icon">${icon('labs')}<h2>Biochemical data</h2><span class="badge">Optional</span></div><p>Record investigations and their clinical context.</p></div>${icon(labsOpen?'close':'plus')}</button>${labsOpen?`<div class="biochem-fields"><p class="lab-caption">Use the units shown. Labs are recorded for clinician interpretation; they do not automatically change macro percentages or diagnose conditions.</p><div class="form-grid"><div class="field full"><label for="lab-date">Investigation date</label><input id="lab-date" data-field="biochem.labDate" type="date" value="${esc(p.biochem.labDate||'')}"></div>${labFields.map(([key,label,unit])=>field(label,'biochem.'+key,p.biochem[key],unit)).join('')}<div class="field full"><label for="lab-notes">Other findings & interpretation</label><textarea id="lab-notes" data-field="biochem.notes">${esc(p.biochem.notes||'')}</textarea></div></div></div>`:''}</section><section class="card card-pad"><label class="field-label" for="clinical-notes">Clinical notes, conditions, medication & goals</label><textarea id="clinical-notes" data-field="notes" placeholder="Add conditions, allergies and your rationale for the prescription…">${esc(p.notes)}</textarea></section></div><div class="stack"><section class="card card-pad plate-card"><div class="eyebrow" style="margin-bottom:10px">THE CLINICAL WORKFLOW</div><h2>Every gram has a place.</h2><p class="field-hint">Set targets, prescribe food exchanges, then reconcile every meal.</p>${plateArt()}<div class="protocol-flow"><span>Weight × activity → TER</span><span>Macro targets → major / minor CHO</span><span>11 food exchanges → DDP totals</span><span>Editable meal cells → reconciled rows</span></div></section><div class="tip-card">${icon('info')}<div><h3>The weight is a clinical decision</h3><p>Record your selected calculation weight and rationale before setting targets. The activity factor is applied directly to that weight.</p></div></div>${sourceNote()}</div></div>`;}
function targetsPage(){const p=current(),s=p.protocol;return `<div class="stack"><div class="content-grid"><div class="stack"><section class="card card-pad"><div class="card-head"><div><h2>Energy into macronutrients</h2><p>Percentages must total 100%. Targets use 4 / 4 / 9 kcal per gram.</p></div><span class="macro-total" id="macro-total">${num((s.carbs||0)+(s.protein||0)+(s.fat||0))} / 100%</span></div><div class="macro-fields">${field('CHO','protocol.carbs',s.carbs,'%',{max:100})}${field('Protein','protocol.protein',s.protein,'%',{max:100})}${field('Fat','protocol.fat',s.fat,'%',{max:100})}</div><label class="toggle-check" style="margin-top:20px"><input type="checkbox" data-field="protocol.roundMacroTargets" ${s.roundMacroTargets?'checked':''}>Use whole-gram targets, as in the reference example</label><div id="target-summary" style="margin-top:20px">${targetSummary()}</div></section><section class="card card-pad"><div class="card-head"><div><h2>Allocate the minor carbohydrate</h2><p>Choose a total, then explicitly divide it among the six minor sources.</p></div><span class="badge">Step 1</span></div>${field('Minor CHO target','protocol.minorCHO',s.minorCHO,'g')}<div class="form-grid" style="margin-top:22px">${minorGroups.map(([id,label])=>field(label,'protocol.minorAllocations.'+id,s.minorAllocations[id],'g CHO')).join('')}</div><div id="minor-status" style="margin-top:16px">${minorStatus()}</div><div class="field" style="margin-top:20px"><label for="minor-rationale">Clinical rationale for the minor-source split</label><textarea id="minor-rationale" data-field="protocol.minorRationale" placeholder="Explain the chosen allocation and patient-specific considerations…">${esc(s.minorRationale||'')}</textarea></div></section></div><div class="stack"><section class="card card-pad"><div class="card-head"><div><h2>The major CHO balance</h2><p>The remaining carbohydrate goes to cereals and pulses.</p></div><span class="badge">Step 2</span></div><div id="major-summary">${majorSummary()}</div><p class="field-hint" style="margin-top:18px">Cereals receive 7/8 and pulses 1/8 of major CHO. Raw gram quantities remain freely editable; no whole-portion rounding is imposed.</p></section><section class="card card-pad"><h3>Plan acceptance</h3><div class="field" style="margin-top:17px"><label for="match-mode">DDP validation rule</label><select id="match-mode" data-field="protocol.matchMode"><option value="allowances" ${s.matchMode==='allowances'?'selected':''}>Within documented allowances</option><option value="exact" ${s.matchMode==='exact'?'selected':''}>Exact target match (within 0.1 g / kcal)</option></select></div><div class="form-grid" style="margin-top:18px">${nutrients.map(([id,label,unit])=>field(label+' allowance ±','protocol.tolerances.'+id,s.tolerances[id],unit)).join('')}</div><p class="field-hint">Reference allowances: energy ±100 kcal, CHO ±25 g, protein ±10 g, fat ±5 g. Meal-row reconciliation and CHO allocation checks remain mandatory. For exact matching, turn off whole-gram rounding: rounding can make the macro-derived energy differ from TER.</p><hr class="section-divider">${field('Dietary fibre target (optional)','protocol.fiberTarget',s.fiberTarget,'g')}<p class="field-hint">The example uses 35.4 g, with a 30.4–50.4 g range. The supplied exchange table contains no fibre data, so the app cannot compute or verify achieved fibre.</p></section></div></div><div class="form-footer"><button class="btn" data-step="0">Back</button><button class="btn primary" data-step="2">Build DDP matrix ${icon('arrow')}</button></div>${sourceNote()}</div>`;}
function targetSummary(){const a=assessment(),s=current().protocol;return `<div class="formula-box"><strong>${num(a.anthropometrics?.calculationWeightKg,2)} kg × ${num(s.activityFactor)} = ${num(a.energy?.ter,1)} kcal</strong><br>TER uses the selected calculation weight, not automatically the actual weight.</div><div class="target-mini-grid">${['carbs','protein','fat'].map((id,i)=>`<div><span>${['CHO','Protein','Fat'][i]}</span><strong>${num(a.macros?.targetGrams?.[id],s.roundMacroTargets?0:3)} <small>g</small></strong><small>Exact: ${num(a.macros?.exactGrams?.[id],3)} g</small></div>`).join('')}</div>`;}
function minorStatus(){const total=minorSum(),target=current().protocol.minorCHO,valid=Number.isFinite(target)&&Math.abs(total-target)<.01&&minorGroups.every(([id])=>Number.isFinite(current().protocol.minorAllocations[id])&&current().protocol.minorAllocations[id]>=0);return `<div class="${valid?'reconcile good':'reconcile bad'}">${icon(valid?'check':'info')}Allocated ${num(total,2)} / ${num(target,2)} g CHO ${valid?'— matches':'— revise the six allocations'}</div>`;}
function majorSummary(){const a=assessment(),c=a.carbohydrateSplit;return `<div class="formula-box"><strong>${num(a.macros?.targetGrams?.carbs,3)} g total − ${num(current().protocol.minorCHO,2)} g minor</strong><br>= ${num(c?.majorTarget,3)} g major carbohydrate</div><div class="major-row"><span>Cereals · 7/8</span><strong>${num(c?.cerealsCHO,3)} g CHO</strong><small>${num(c?.cerealsCHO/20*30,3)} g raw</small></div><div class="major-row"><span>Pulses · 1/8</span><strong>${num(c?.pulsesCHO,3)} g CHO</strong><small>${num(c?.pulsesCHO/17*30,3)} g raw</small></div>`;}
function tracker(){const a=assessment(),r=ddpResult(),target=targetValues(a),tol=current().protocol.tolerances;return `<div class="ddp-trackers">${nutrients.map(([key,label,unit])=>{const actual=r.totals?.[key],wanted=target[key],remaining=Number.isFinite(wanted)&&Number.isFinite(actual)?wanted-actual:null,pass=Number.isFinite(remaining)&&Math.abs(remaining)<=(current().protocol.matchMode==='exact'?.1:tol[key]);return `<div class="tracker ${pass?'good':'bad'}"><div class="row between"><span>${label}</span>${icon(pass?'check':'info')}</div><strong>${num(actual,1)}<small> / ${num(wanted,1)} ${unit}</small></strong><p>${Number.isFinite(remaining)?`${remaining>=0?'Remaining':'Over target'}: ${num(Math.abs(remaining),1)} ${unit}`:'Complete target inputs'}</p><small>${current().protocol.matchMode==='exact'?'Exact match: ±0.1 '+unit:`Allowed: ${num(wanted-tol[key],1)}–${num(wanted+tol[key],1)} ${unit}`}</small></div>`;}).join('')}</div>`;}
function ddpPage(){const a=assessment();return `<div class="stack"><div id="ddp-tracker">${tracker()}</div><section class="card"><div class="card-pad"><div class="card-head"><div><h2>Daily diet prescription</h2><p>Enter raw quantities or fractional portions. All 11 food groups contribute to the running macro totals.</p></div><button class="btn soft" data-action="seed-ddp" ${!a.eligible?'disabled':''}>${icon('grid')}Apply CHO allocation</button></div><p class="field-hint">Apply CHO allocation fills cereals, pulses and the six minor sources from your targets. Meat, eggs and oil remain your choice. Existing meal allocations are retained and any mismatch is highlighted.</p></div><div class="table-scroll"><table class="portion-table ddp-table"><thead><tr><th>Food group</th><th>Raw g / ml</th><th>Portions</th><th>CHO g</th><th>PRO g</th><th>FAT g</th><th>kcal</th></tr></thead><tbody>${foods().map(f=>ddpRow(f)).join('')}</tbody><tfoot id="ddp-totals">${ddpTotals()}</tfoot></table></div><div class="card-pad"><div id="ddp-checks">${ddpChecks()}</div><p class="field-hint">Energy is calculated from the exchange macros at 4 / 4 / 9 kcal/g. Fractional portions and raw quantities are retained at calculation precision; displayed values are rounded.</p></div></section><div class="content-grid"><section class="card card-pad"><h3>Protein and fat are a clinical choice</h3><p class="small muted" style="margin-top:12px">Adjust the appropriate food groups while watching the balance above. The app does not automatically prescribe meat, eggs or oil to close a deficit. When you edit a carbohydrate-containing food, the CHO allocation check updates too.</p></section><section class="card card-pad"><h3>Recipe and fibre limits</h3><p class="small muted" style="margin-top:12px">These are the fixed exchange constants supplied in your specification, not a recipe-level nutrient database. Fibre target: ${num(current().protocol.fiberTarget,1)} g. Achieved fibre is unavailable without additional food-composition data.</p></section></div><div class="form-footer"><button class="btn" data-step="1">Back to targets</button><button class="btn primary" data-step="3">Divide across meals ${icon('arrow')}</button></div></div>`;}
function ddpRow(f){const r=ddpResult().rows?.find(x=>x.id===f.id),q=current().ddp[f.id];return `<tr><td>${esc(f.label)}<small>${f.portionSize} ${fieldUnit(f)} / portion</small></td><td><input data-ddp="${f.id}" type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(f.label)} raw quantity" value="${esc(q??'')}"></td><td><input data-ddp-portions="${f.id}" type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(f.label)} portions" value="${Number.isFinite(q)?Number((q/f.portionSize).toFixed(6)):''}"></td>${['carbs','protein','fat','energy'].map(k=>`<td data-food-value="${f.id}:${k}">${num(r?.[k],2)}</td>`).join('')}</tr>`;}
function ddpTotals(){const r=ddpResult();return `<tr><td colspan="3"><strong>DDP total</strong></td>${['carbs','protein','fat','energy'].map(k=>`<td><strong>${num(r.totals?.[k],2)}</strong></td>`).join('')}</tr>`;}
function choReconciliation(){const a=assessment(),rows=ddpResult().rows||[],actual=id=>rows.find(r=>r.id===id)?.carbs,targets={cereals:a.carbohydrateSplit?.cerealsCHO,pulses:a.carbohydrateSplit?.pulsesCHO,...current().protocol.minorAllocations};return ['cereals','pulses',...minorGroups.map(([id])=>id)].map(id=>({id,label:foodById(id)?.label||id,actual:actual(id),target:targets[id],matches:Number.isFinite(actual(id))&&Number.isFinite(targets[id])&&Math.abs(actual(id)-targets[id])<=.1}));}
function ddpChecks(){const r=ddpResult(),checks=choReconciliation(),mismatches=checks.filter(c=>!c.matches),valid=r.errors?.length===0;return `${(r.errors||[]).map(e=>`<div class="alert error">${esc(e)}</div>`).join('')}<div class="reconcile ${valid&&!mismatches.length?'good':'bad'}">${icon(valid&&!mismatches.length?'check':'info')}CHO-source reconciliation: ${checks.length-mismatches.length} / ${checks.length} allocations match within 0.1 g</div>${mismatches.length?`<div class="allocation-chips">${mismatches.map(c=>`<span>${esc(c.label)}: ${num(c.actual,2)} / ${num(c.target,2)} g CHO</span>`).join('')}</div>`:''}<p class="field-hint">DDP acceptance: ${current().protocol.matchMode==='exact'?'exact targets within 0.1 g / kcal':'within the selected allowances'}. Source allocation and meal-row checks must also reconcile.</p>`;}
function mealPage(){const p=current();return `<div class="stack"><section class="card card-pad"><div class="card-head"><div><h2>Make room for every meal</h2><p>Configure meal names and timings. Allocate each food group independently.</p></div><button class="btn" data-action="add-meal" ${p.protocolMeals.length>=8?'disabled':''}>${icon('plus')}Add meal</button></div><div class="meal-config">${p.protocolMeals.map((m,i)=>`<div class="meal-config-item"><div class="row between"><span class="eyebrow">MEAL ${i+1}</span><button class="icon-btn" aria-label="Remove ${esc(m.label)}" data-remove-meal="${esc(m.id)}" ${p.protocolMeals.length<=1?'disabled':''}>${icon('close')}</button></div><label class="field-label" for="meal-${i}-label">Name</label><input id="meal-${i}-label" data-field="protocolMeals.${i}.label" value="${esc(m.label)}" maxlength="40"><label class="field-label" for="meal-${i}-time" style="margin-top:12px">Time</label><input id="meal-${i}-time" data-field="protocolMeals.${i}.time" value="${esc(m.time)}" maxlength="30"></div>`).join('')}</div></section><section class="card"><div class="card-pad"><div class="card-head"><div><h2>Portion division matrix</h2><p>Each row must sum to its prescribed DDP quantity.</p></div><span id="distribution-badge">${distributionBadge()}</span></div><div class="alert info">Cereals and pulses use <strong>raw grams</strong> in meal cells. All other rows use <strong>portions</strong>, including fractions. The units are printed beside every row.</div><div class="row wrap no-print"><button class="btn soft" data-action="distribute-evenly">Divide evenly as a starting point</button><button class="btn" data-action="clear-distribution">Clear meal allocations</button></div></div><div class="table-scroll" id="meal-grid">${mealGrid(true)}</div><div class="card-pad"><p class="field-hint">Green rows reconcile; red rows are under or over their DDP prescription. Editing DDP amounts later does not silently redistribute the foods.</p></div></section><section class="card card-pad"><h2>Food choices and preparation</h2>${p.protocolMeals.map((m,i)=>`<div class="meal-card"><h3>${esc(m.label)} <span class="small muted">${esc(m.time)}</span></h3><textarea data-field="protocolMeals.${i}.note" aria-label="${esc(m.label)} instructions" placeholder="Specify food items, preparation and cooked serving guidance…">${esc(m.note)}</textarea></div>`).join('')}<div class="form-footer"><button class="btn" data-step="2">Back to DDP</button><button class="btn primary" data-step="4">Review prescription ${icon('arrow')}</button></div></section></div>`;}
function distributionBadge(){const rows=foods().map(rowDistribution);return `<span class="badge ${rows.every(r=>r.matches)&&rows.length===11?'':'warning'}">${rows.filter(r=>r.matches).length} / 11 rows reconciled</span>`;}
function rowDistribution(f){const p=current(),values=p.protocolMeals.map(m=>p.distribution[f.id]?.[m.id]),prescribed=rawMeal(f.id)?p.ddp[f.id]:Number.isFinite(p.ddp[f.id])?p.ddp[f.id]/f.portionSize:null,allocated=values.reduce((s,v)=>s+(Number(v)||0),0),valid=Number.isFinite(prescribed)&&values.every(v=>Number.isFinite(v)&&v>=0);return {prescribed,allocated,delta:valid?allocated-prescribed:null,matches:valid&&Math.abs(allocated-prescribed)<=.0001};}
function mealGrid(editable){const p=current();return `<table class="portion-table meal-matrix"><thead><tr><th>Food group / unit</th><th>DDP total</th>${p.protocolMeals.map(m=>`<th>${esc(m.label)}<small>${esc(m.time)}</small></th>`).join('')}<th>Allocated</th><th>Balance</th></tr></thead><tbody>${foods().map(f=>{const r=rowDistribution(f);return `<tr data-distribution-row="${f.id}" class="${r.matches?'row-good':'row-bad'}"><td>${esc(f.label)}<small>${rawMeal(f.id)?'raw g':`portions · ${f.portionSize} ${fieldUnit(f)} each`}</small></td><td>${num(r.prescribed,3)}</td>${p.protocolMeals.map(m=>`<td>${editable?`<input type="number" min="0" step="any" inputmode="decimal" data-grid-food="${f.id}" data-grid-meal="${esc(m.id)}" aria-label="${esc(f.label)} at ${esc(m.label)} ${rawMeal(f.id)?'raw grams':'portions'}" value="${esc(p.distribution[f.id]?.[m.id]??'')}">`:num(p.distribution[f.id]?.[m.id],3)}</td>`).join('')}<td data-row-allocated="${f.id}">${num(r.allocated,3)}</td><td data-row-status="${f.id}" class="${r.matches?'status-positive':'status-negative'}">${r.matches?'✓ Matched':Number.isFinite(r.delta)?`${r.delta>0?'+':''}${num(r.delta,3)}`:'Enter all cells'}</td></tr>`;}).join('')}</tbody></table>`;}
function finalChecks(){const a=assessment(),r=ddpResult(),cho=choReconciliation(),rows=foods().map(rowDistribution),accepted=current().protocol.matchMode==='exact'?r.exactMatch:r.withinAllowances?.all;return [{ok:a.eligible,label:'Assessment, macro percentages and minor allocation valid'},{ok:!r.errors?.length&&Boolean(accepted),label:current().protocol.matchMode==='exact'?'DDP matches exact targets':'DDP falls within the chosen nutrient allowances'},{ok:cho.every(c=>c.matches),label:'Major and minor CHO source allocations reconcile'},{ok:rows.length===11&&rows.every(r=>r.matches),label:'All 11 food-group meal rows match the DDP'},{ok:current().protocolMeals.every(m=>m.label.trim()),label:'Every meal has a name'}];}
function reviewPage(){const p=current(),a=assessment(),r=ddpResult(),t=targetValues(),checks=finalChecks(),ready=checks.every(c=>c.ok);return `<div class="content-grid"><article class="card protocol-print"><header class="review-header"><div class="eyebrow">NOURISH · DIETICIAN REFERENCE</div><h2>${esc(p.name)}</h2><p>${p.age??'—'} years · ${p.sex==='male'?'Male':'Female'} · ${esc(p.activity)} activity</p><span class="badge ${p.demo?'demo':''}" style="margin-top:12px">${p.demo?'REFERENCE EXAMPLE — NOT A PRESCRIPTION':p.protocolReviewedAt?'REVIEWED '+shortDate(p.protocolReviewedAt):'DRAFT — NOT FINALISED'}</span></header><div class="card-pad"><h3>Anthropometry & target computation</h3><div class="review-meta"><div>Actual weight<strong>${num(p.weight,2)} kg</strong></div><div>Height<strong>${num(p.height,1)} cm</strong></div><div>BMI<strong>${num(a.anthropometrics?.bmi,1)}</strong></div><div>Weight used<strong>${num(a.anthropometrics?.calculationWeightKg,2)} kg</strong><small>${esc(a.anthropometrics?.weightSource||'')}</small></div></div><p class="small muted">${esc(a.anthropometrics?.asianIndianCategory||'')} · TER = ${num(a.anthropometrics?.calculationWeightKg,2)} × ${num(p.protocol.activityFactor)} = <strong>${num(a.energy?.ter,1)} kcal/day</strong>.</p><p class="small muted" style="margin-top:9px">CHO ${num(t.carbs,3)} g (${num(p.protocol.carbs)}%) · PRO ${num(t.protein,3)} g (${num(p.protocol.protein)}%) · FAT ${num(t.fat,3)} g (${num(p.protocol.fat)}%). ${p.protocol.roundMacroTargets?`Whole-gram planning targets. Exact values: CHO ${num(a.macros?.exactGrams?.carbs,3)}, PRO ${num(a.macros?.exactGrams?.protein,3)}, FAT ${num(a.macros?.exactGrams?.fat,3)} g.`:'Unrounded planning targets.'}</p><h3 class="review-section">Target ranges & DDP achievement</h3><div class="table-scroll"><table class="portion-table"><thead><tr><th>Nutrient</th><th>Target</th><th>Allowed range</th><th>DDP actual</th></tr></thead><tbody>${nutrients.map(([k,label,unit])=>`<tr><td>${label} (${unit})</td><td>${num(t[k],2)}</td><td>${num(t[k]-p.protocol.tolerances[k],2)}–${num(t[k]+p.protocol.tolerances[k],2)}</td><td>${num(r.totals?.[k],2)}</td></tr>`).join('')}</tbody></table></div><p class="field-hint">Fibre target: ${num(p.protocol.fiberTarget,1)} g. ${Number.isFinite(p.protocol.fiberTarget)?`Reference-style range: ${num(Math.max(0,p.protocol.fiberTarget-5),1)}–${num(p.protocol.fiberTarget+15,1)} g.`:''} Achieved fibre cannot be verified from the supplied exchange constants.</p><h3 class="review-section">Major and minor carbohydrate</h3><p class="small muted">Minor CHO: ${num(p.protocol.minorCHO,2)} g. ${minorGroups.map(([id,label])=>`${label} ${num(p.protocol.minorAllocations[id],2)} g`).join(' · ')}.</p><p class="small muted" style="margin-top:9px">Major CHO: ${num(a.carbohydrateSplit?.majorTarget,3)} g → cereals ${num(a.carbohydrateSplit?.cerealsCHO,3)} g CHO (7/8), pulses ${num(a.carbohydrateSplit?.pulsesCHO,3)} g CHO (1/8).</p>${p.protocol.minorRationale?`<p class="review-notes">${esc(p.protocol.minorRationale)}</p>`:''}<h3 class="review-section">DDP matrix · raw weights</h3><div class="table-scroll"><table class="portion-table"><thead><tr><th>Food group</th><th>Raw quantity</th><th>Portions</th><th>CHO</th><th>PRO</th><th>FAT</th></tr></thead><tbody>${(r.rows||[]).map(row=>`<tr><td>${esc(row.label)}</td><td>${num(row.quantity,3)} ${fieldUnit(row)}</td><td>${num(row.portions,3)}</td><td>${num(row.carbs,2)}</td><td>${num(row.protein,2)}</td><td>${num(row.fat,2)}</td></tr>`).join('')}</tbody></table></div><h3 class="review-section">Portion division by meal</h3><div class="table-scroll">${mealGrid(false)}</div><p class="field-hint">Cereals and pulses are in raw grams; all other meal cells are in portions. Their row units are explicit.</p><h3 class="review-section">Meal instructions</h3>${p.protocolMeals.map(m=>`<div class="meal-card"><div class="meal-time">${esc(m.time)}</div><h3>${esc(m.label)}</h3><p class="review-notes" style="margin-top:8px">${esc(m.note||'Food choices and preparation to be specified by the clinician.')}</p></div>`).join('')}${p.notes?`<h3 class="review-section">Clinical notes</h3><p class="review-notes">${esc(p.notes)}</p>`:''}${labReport()}<hr class="section-divider"><p class="small muted">Basis: supplied Clinical Diet Protocol developer specification; fixed exchange macros at 4 / 4 / 9 kcal/g. Acceptance rule: ${p.protocol.matchMode==='exact'?'exact targets':'selected nutrient allowances'}, plus CHO-source and meal reconciliation.</p><div class="print-only" style="margin-top:25px">Clinician: ____________________ &nbsp; Signature: ____________________<p style="margin-top:12px">Prepared ${shortDate(iso())}</p></div></div></article><div class="stack no-print"><section class="card card-pad"><h2>Prescription checks</h2><div class="final-checks">${checks.map(c=>`<div class="${c.ok?'status-positive':'status-negative'}">${icon(c.ok?'check':'info')}<span><strong>${c.ok?'Pass':'Needs attention'}</strong> · ${c.label}</span></div>`).join('')}</div><label class="toggle-check review-check"><input id="review-confirm" type="checkbox" ${p.protocolReviewedAt?'checked':''}>I have reviewed this patient’s prescription.</label><button class="btn primary" style="width:100%" data-action="review" ${!ready||p.demo?'disabled':''}>${icon('check')}Save finalised plan</button><button class="btn" style="width:100%;margin-top:12px" data-action="print">${icon('print')}Print / save as PDF</button><p class="field-hint">Unfinalised output is labelled DRAFT. Examples remain labelled and cannot be saved as reviewed patients.</p></section><section class="card card-pad"><h3>Protocol review history</h3>${p.protocolHistory.length?p.protocolHistory.slice().reverse().map((h,i)=>`<div class="revision row between"><div><strong>${shortDate(h.reviewedAt)}</strong><p>${num(h.energy)} kcal · ${num(h.protein,1)} g protein</p></div><button class="btn small-btn" data-history="${p.protocolHistory.length-1-i}">View</button></div>`).join(''):'<p class="field-hint">Finalised snapshots are kept here.</p>'}</section><button class="btn" data-step="2">Return to DDP matrix</button></div></div>`;}
function labReport(){const p=current(),entries=labFields.filter(([id])=>p.biochem[id]!==undefined&&p.biochem[id]!==null&&p.biochem[id]!=='');if(!entries.length&&!p.biochem.notes)return '';return `<h3 class="review-section">Biochemical data ${p.biochem.labDate?'· '+shortDate(p.biochem.labDate):''}</h3><p class="small muted">${entries.map(([id,label,unit])=>`${label}: ${esc(p.biochem[id])} ${unit}`).join(' · ')}</p>${p.biochem.notes?`<p class="review-notes">${esc(p.biochem.notes)}</p>`:''}`;}
function patientList(){return `${heading('A healthier day, for every patient.','Assessments, daily diet prescriptions and follow-up plans, stored locally.')}<div class="welcome-banner"><div><div class="eyebrow" style="margin-bottom:12px">CLINICAL NUTRITION, ACCOUNTED FOR</div><h2>From targets to the patient’s plate.</h2><p>Build an exchange-based prescription, then make every food group balance across the day.</p><button class="btn soft" data-action="demo">Explore example workspace ${icon('arrow')}</button></div>${plateArt()}</div><div class="row between wrap" style="margin-top:28px"><h2>Your patients <span class="badge">${activePatients().length}</span></h2><div class="patient-search">${icon('search')}<input id="patient-search" aria-label="Search patients" placeholder="Search patient names…" value="${esc(query)}"></div></div><div class="patients-grid" id="patient-cards">${patientCards()}</div>`;}
function patientCards(){const list=activePatients().filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(p=>{const a=calculateProtocol(p,p.protocol);return `<button class="card patient-tile" data-patient="${esc(p.id)}"><div class="row between"><span class="avatar">${esc(initials(p.name))}</span><span class="badge">${p.protocolReviewedAt?'Reviewed':'Draft'}</span></div><h3>${esc(p.name)}</h3><p>${p.age??'—'} years · Updated ${shortDate(p.updatedAt)}</p><div class="tile-metrics"><div>BMI<b>${num(a.anthropometrics?.bmi,1)}</b></div><div>TER<b>${num(a.energy?.ter)} kcal</b></div></div></button>`;}).join(''):`<div class="card empty-state"><div class="empty-icon">${icon('people')}</div><h2>${query?'No patients found':'Your next plan starts here.'}</h2><p>${query?'Try another name.':'Add a patient to begin their assessment and daily diet prescription.'}</p>${query?'':`<button class="btn primary" data-action="add">${icon('plus')}Add your first patient</button>`}</div>`;}
function referencePage(){return `${heading('The protocol behind the prescription.','The supplied documents now define the workflow; their arithmetic is checked explicitly.',false)}<section class="card card-pad" style="margin-bottom:22px"><div class="card-head"><div><h2>What changed from the first version</h2><p>Clinical protocol calculations replace population references and plate scaling.</p></div>${icon('book')}</div><div class="table-scroll"><table class="portion-table"><thead><tr><th>Calculation</th><th>First version</th><th>Supplied protocol</th></tr></thead><tbody><tr><td>TER</td><td>ICMR reference kcal/day or scaled reference</td><td>Selected weight × 25 / 30 / 35–40</td></tr><tr><td>TER weight</td><td>Prior manual selection</td><td>Actual below BMI 23; ABW at BMI ≥23; IBW or custom also selectable</td></tr><tr><td>Food quantities</td><td>Proportional NIN My Plate quantities</td><td>11 fixed exchanges with live macro accounting</td></tr><tr><td>CHO split</td><td>No major/minor allocation</td><td>Explicit minor allocation; remaining CHO split 7/8 and 1/8</td></tr><tr><td>Meals</td><td>Same percentage applied to each group</td><td>Independent editable food-group × meal cells</td></tr></tbody></table></div></section><div class="reference-grid"><section class="card card-pad reference-card"><h2>Rules from the developer specification</h2><ul><li>BMI = actual kg ÷ height in metres squared.</li><li>TER = selected kg × activity factor; sedentary 25, moderate 30, heavy 35–40.</li><li>CHO and protein grams = TER × percentage ÷ 4; fat uses ÷ 9.</li><li>Define minor CHO and allocate it among six groups.</li><li>Major CHO = total CHO − minor CHO; cereals receive 7/8 and pulses 1/8.</li><li>Each food-group meal row must match its prescribed DDP amount.</li></ul><p>The document calls these ICMR portions. The app attributes the exact constants and weight formulas to the supplied clinical instructions; it does not assert that this whole protocol is an official ICMR guideline.</p></section><section class="card card-pad reference-card"><h2>Rounding, allowances and clinical scope</h2><p>The reference case rounds 199.125 g CHO to 199 g and 110.625 g protein to 111 g. Whole-gram planning is the default; exact gram targets can be selected.</p><p style="margin-top:12px">Default allowances follow the example: energy ±100 kcal, CHO ±25 g, protein ±10 g and fat ±5 g. You can instead require exact targets. CHO-source and meal-row reconciliation are mandatory in either mode.</p><p style="margin-top:12px">Underweight uses the WHO 18.5 threshold; overweight and obesity use Asian Indian action thresholds 23 and 25. Children, pregnancy and lactation require a separate protocol. Fibre cannot be verified without fibre constants.</p></section><section class="card card-pad reference-card"><h2>Reference case: what reconciles</h2><p>The provided case has IBW <strong>53.36 kg</strong> and calculated ABW <strong>58.96 kg</strong>, rounded to 59 kg for TER: <strong>59 × 30 = 1,770 kcal</strong>. Its 45 / 25 / 30 split gives rounded targets of 199 g CHO, 111 g protein and 59 g fat.</p><p style="margin-top:12px">Using the supplied DDP raw weights and exchange constants gives <strong>1,697.67 kcal, 196.96 g CHO, 101.46 g protein and 56 g fat</strong>. These fall inside the example’s stated allowances, although they are not exact matches.</p><button class="btn soft" style="margin-top:18px" data-action="reference-example">Load supplied example for inspection</button><p class="field-hint">Loaded as an unsaved reference, never as a new patient record.</p></section><section class="card card-pad reference-card"><h2>Reference case: mismatches preserved</h2><ul><li>Declared minor CHO: 70 g. The listed raw weights provide 68 g: milk 15, GLV 3, other vegetables 15, roots 15, fruit 20, sugar 0.</li><li>Cereals: five meal portions represent 150 g, versus the DDP’s 169.3 g.</li><li>Pulses: two meal portions represent 60 g, versus the DDP’s 28.4 g.</li><li>Other vegetables: two meal portions represent 200 g, versus the DDP’s 300 g.</li></ul><p>The app reports these discrepancies and prevents finalisation until the inputs reconcile. “Apply CHO allocation” regenerates raw amounts from the stated CHO targets; it does not silently change the source example.</p></section></div><section class="card card-pad" style="margin-top:22px"><h2>Exchange constants used</h2><div class="table-scroll" style="margin-top:18px"><table class="portion-table"><thead><tr><th>Food group</th><th>One portion</th><th>CHO g</th><th>PRO g</th><th>FAT g</th></tr></thead><tbody>${foods().map(f=>`<tr><td>${esc(f.label)}</td><td>${f.portionSize} ${fieldUnit(f)}</td><td>${num(f.carbs,1)}</td><td>${num(f.protein,1)}</td><td>${num(f.fat,1)}</td></tr>`).join('')}</tbody></table></div><p class="field-hint">Sources supplied by the user: Developer Spec–Clinical Diet Protocol App.docx; Dietician Reference–Sajitha K M.docx. The original files remain unchanged.</p><div class="source-links">${PROTOCOL_SOURCES.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></p>`).join('')}</div></section>`;}
function settingsPage(){return `${heading('Your workspace. Your device.','Patient data, backups and local app installation.',false)}<div class="content-grid"><section class="card card-pad"><h2>Device & patient data</h2><p class="field-hint">${activePatients().length} active · ${patients.filter(p=>p.archivedAt).length} archived records.</p><div class="settings-options"><div class="setting-row"><div><h3>Export a backup</h3><p>Includes patient inputs, DDP matrices, meal grids and review snapshots.</p></div><button class="btn" data-action="export">${icon('download')}Export</button></div><div class="setting-row"><div><h3>Import a backup</h3><p>Preview and add new IDs. Existing records are not overwritten.</p></div><button class="btn" data-action="import">${icon('upload')}Import</button></div><div class="setting-row"><div><h3>Install Nourish</h3><p>Use a supported browser’s install or home-screen option.</p></div><button class="btn" data-action="install">${icon('download')}Install</button></div>${storageBlocked?'<div class="setting-row"><div><h3>Recover stored content</h3><p>Download original storage before attempting repair.</p></div><button class="btn" data-action="recover">Export original</button></div>':''}</div>${patients.some(p=>p.archivedAt)?`<hr class="section-divider"><h3>Archived patients</h3>${patients.filter(p=>p.archivedAt).map(p=>`<div class="setting-row" style="margin-top:12px"><div><h3>${esc(p.name)}</h3><p>Archived ${shortDate(p.archivedAt)}</p></div><button class="btn small-btn" data-restore="${esc(p.id)}">Restore patient</button></div>`).join('')}`:''}</section><div class="stack"><section class="card card-pad"><h2>Local data, explicitly</h2><p class="small muted" style="margin-top:15px">No cloud database or patient upload. Records and JSON backups are <strong>not encrypted</strong>. Use a protected device and keep secure backups.</p><hr class="section-divider"><p class="small muted">Browser storage belongs to the exact address and profile. Clearing it erases records. localhost and 127.0.0.1 have separate storage.</p><hr class="section-divider"><p class="small muted">Earlier-version settings and history are retained in backups. They do not automatically become finalised plans under this new protocol.</p></section><div class="tip-card">${icon('download')}<div><h3>Installing on a phone</h3><p>Use an HTTPS address reachable by the phone. A computer’s localhost address cannot be opened from another device. Once cached, the app works offline.</p></div></div></div></div>`;}

function updateDerived(){if(route!=='planner')return;const dynamic={metrics,validation,'weight-choice':weightChoice,'target-summary':targetSummary,'minor-status':minorStatus,'major-summary':majorSummary,'ddp-tracker':tracker,'ddp-totals':ddpTotals,'ddp-checks':ddpChecks,'distribution-badge':distributionBadge};if(document.activeElement?.dataset.field==='protocol.customWeight')delete dynamic['weight-choice'];for(const [id,fn] of Object.entries(dynamic)){const node=$('#'+id);if(node)node.innerHTML=fn();}const mt=$('#macro-total'),s=current().protocol;if(mt)mt.textContent=num((s.carbs||0)+(s.protein||0)+(s.fat||0))+' / 100%';for(const row of ddpResult().rows||[])for(const key of ['carbs','protein','fat','energy']){const node=$(`[data-food-value="${row.id}:${key}"]`);if(node)node.textContent=num(row[key],2);}for(const f of foods()){const r=rowDistribution(f),row=$(`[data-distribution-row="${f.id}"]`),allocated=$(`[data-row-allocated="${f.id}"]`),status=$(`[data-row-status="${f.id}"]`);if(row)row.className=r.matches?'row-good':'row-bad';if(allocated)allocated.textContent=num(r.allocated,3);if(status){status.className=r.matches?'status-positive':'status-negative';status.textContent=r.matches?'✓ Matched':Number.isFinite(r.delta)?`${r.delta>0?'+':''}${num(r.delta,3)}`:'Enter all cells';}}}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<button class="icon-btn dialog-close" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button><h2 id="dialog-title">${title}</h2>${body}`;if(!d.open)d.showModal();}
function patientDialog(edit=false){modal(edit?'Patient details':'Meet your next patient',`<p class="dialog-desc">${edit?'Manage this patient’s details or archive the record.':'Enter a name or identifier, then complete the clinical assessment.'}</p><form id="patient-form" data-edit="${edit}"><div class="field"><label for="patient-name">Patient name or identifier</label><input id="patient-name" required maxlength="100" autofocus value="${edit?esc(current().name):''}"></div><div id="dialog-error" class="dialog-error" role="alert"></div><div class="dialog-actions">${edit?`<button class="btn danger" type="button" data-action="archive">${icon('trash')}Archive patient</button>`:'<button class="btn" type="button" data-action="close-dialog">Cancel</button>'}<button class="btn primary" type="submit">${edit?'Save details':'Create patient'}</button></div></form>`);}
function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function referenceExample(){const meals=[['breakfast','Breakfast','8:00 AM'],['lunch','Lunch','1:00 PM'],['evening','Evening','4:30 PM'],['dinner','Dinner','7:30 PM']].map(([id,label,time])=>({id,label,time,note:''}));const values={cereals:[60,60,0,30],pulses:[30,0,0,30],milk:[1,0,1,1],glv:[0,1,0,0],otherVeg:[1,1,0,0],roots:[0,1,0,0],fruit:[0,0,2,0],meat:[0,2,0,2],eggs:[3,0,0,0],oil:[1,1,0,2],sugar:[0,0,0,0]};demo=normalize({id:'demo',name:'Sajitha K M · reference',demo:true,referenceExample:true,age:50,sex:'female',height:154,weight:75.75,activity:'moderate',protocol:{weightMode:'abw',activityFactor:30,carbs:45,protein:25,fat:30,roundMacroTargets:true,minorCHO:70,minorAllocations:{milk:15,glv:5,otherVeg:20,roots:10,fruit:20,sugar:0},fiberTarget:35.4},ddp:{cereals:169.3,pulses:28.4,milk:300,glv:100,otherVeg:300,roots:100,fruit:200,meat:200,eggs:150,oil:20,sugar:0},protocolMeals:meals,distribution:Object.fromEntries(Object.entries(values).map(([id,v])=>[id,Object.fromEntries(meals.map((m,i)=>[m.id,v[i]]))])),biochem:{fastingGlucose:104,ldl:152.4,hdl:37.6,uricAcid:6.3},notes:'Supplied reference: prediabetes, dyslipidemia, borderline hyperuricemia, vitamin D insufficiency; visceral fat grade 16. Moderate activity (1 hr+ gym). These are notes from the supplied case, not app diagnoses.',createdAt:iso(),updatedAt:iso()});selectedId='demo';navigate('planner',1);}
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return;}modal('Install this workspace',`<p class="dialog-desc">Chrome / Edge: use the address-bar install icon or browser menu → Install app.<br><br>iPhone / iPad: in Safari, choose Share → Add to Home Screen.</p><div class="formula-box">${swReady?'Offline assets are cached.':'Load once over HTTPS or localhost to cache the app.'}<br>Phone installation requires HTTPS reachable by that phone. Records stay in the browser where you entered them.</div><div class="dialog-actions"><button class="btn primary" data-action="close-dialog">Got it</button></div>`);}
function saveReview(){if(current().demo||!finalChecks().every(c=>c.ok)){toast('Resolve all prescription checks first.');return;}if(!$('#review-confirm')?.checked){toast('Confirm your clinical review before finalising.');return;}const p=current(),a=assessment(),r=ddpResult(),previous=p.protocolReviewedAt;p.protocolReviewedAt=iso();const snapshot=clone({...p,history:[],protocolHistory:[],calculatedProtocol:{assessment:a,ddp:r}});p.protocolHistory.push({reviewedAt:p.protocolReviewedAt,energy:a.energy.ter,protein:a.macros.targetGrams.protein,snapshot});if(!persist()){p.protocolHistory.pop();p.protocolReviewedAt=previous;return;}render();toast('Finalised protocol snapshot saved.');}
function seedDDP(){const a=assessment();if(!a.eligible){toast('Complete the target and minor-CHO allocation first.');return;}const suggested=suggestDDP(a);for(const row of suggested.rows||[])if(['cereals','pulses',...minorGroups.map(([id])=>id)].includes(row.id))current().ddp[row.id]=suggested.quantities[row.id];for(const id of ['meat','eggs','oil'])if(!Object.hasOwn(current().ddp,id))current().ddp[id]=0;changed();render();toast('CHO-based food amounts applied. Review the protein and fat balance.');}
function distributeEvenly(){const p=current();for(const f of foods()){const q=p.ddp[f.id];if(!Number.isFinite(q)||q<0){toast('Complete all DDP food amounts first.');return;}}for(const f of foods()){const total=rawMeal(f.id)?p.ddp[f.id]:p.ddp[f.id]/f.portionSize,n=p.protocolMeals.length,base=Math.floor(total/n*1e6)/1e6;p.distribution[f.id]=Object.fromEntries(p.protocolMeals.map((m,i)=>[m.id,i===n-1?total-base*(n-1):base]));}changed();render();toast('Food amounts divided evenly. Adjust the cells for the patient.');}

document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a,[data-action]');if(!el)return;
 if(el.dataset.route){navigate(el.dataset.route);return;}if(el.dataset.step!==undefined){navigate('planner',Number(el.dataset.step));return;}if(el.dataset.patient){selectedId=el.dataset.patient;navigate('planner',0);return;}
 if(el.dataset.activity){current().activity=el.dataset.activity;current().protocol.activityFactor=factorFor(el.dataset.activity);changed();render();return;}
 if(el.dataset.restore){const p=patients.find(p=>p.id===el.dataset.restore),previous=p.archivedAt;p.archivedAt=null;try{if(storageBlocked)throw Error(storageBlocked);savePatients(patients);render();toast('Patient restored.');}catch(e){p.archivedAt=previous;toast(e.message);}return;}
 if(el.dataset.removeMeal){const p=current();if(p.protocolMeals.length<=1)return;p.protocolMeals=p.protocolMeals.filter(m=>m.id!==el.dataset.removeMeal);changed();render();toast('Meal removed. Reconcile any displaced food amounts.');return;}
 if(el.dataset.history!==undefined){const h=current().protocolHistory[Number(el.dataset.history)];modal('Saved protocol snapshot',`<p class="dialog-desc">Reviewed ${shortDate(h.reviewedAt)}. This snapshot preserves the patient inputs, targets, DDP and meal grid at review time.</p><div class="formula-box"><strong>${num(h.energy)} kcal/day · ${num(h.protein,1)} g target protein</strong><br>${esc(h.snapshot.name)}</div><div class="dialog-actions"><button class="btn" data-action="close-dialog">Close</button><button class="btn primary" data-export-snapshot="${el.dataset.history}">Export snapshot</button></div>`);return;}
 if(el.dataset.exportSnapshot!==undefined){const h=current().protocolHistory[Number(el.dataset.exportSnapshot)];download(exportBackup([{...clone(h.snapshot),id:crypto.randomUUID(),history:[],protocolHistory:[]}]),`nourish-protocol-${h.reviewedAt.slice(0,10)}.json`);return;}
 switch(el.dataset.action){
 case 'home':event.preventDefault();navigate('patients');break;
 case 'menu':$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('show');syncMenu();break;
 case 'close-menu':$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('show');syncMenu();break;
 case 'close-dialog':$('#dialog').close();break;
 case 'add':patientDialog();break;case 'edit-patient':patientDialog(true);break;
 case 'demo':selectedId='demo';navigate('planner',0);break;
 case 'labs':labsOpen=!labsOpen;render();break;
 case 'use-actual':current().protocol.weightMode='actual';changed();render();break;
 case 'seed-ddp':seedDDP();break;
 case 'add-meal':if(current().protocolMeals.length<8){current().protocolMeals.push({id:crypto.randomUUID(),label:'New meal',time:'',note:''});changed();render();}break;
 case 'distribute-evenly':distributeEvenly();break;
 case 'clear-distribution':current().distribution={};changed();render();break;
 case 'review':saveReview();break;case 'print':window.print();break;
 case 'reference-example':referenceExample();break;
 case 'install':await install();break;
 case 'export':try{download(exportBackup(patients),`nourish-backup-${iso().slice(0,10)}.json`);toast('Backup downloaded. Store it securely.');}catch(e){toast(e.message);}break;
 case 'import':$('#import-file').click();break;
 case 'confirm-import':if(pendingImport&&!storageBlocked){const ids=new Set(patients.map(p=>p.id)),added=pendingImport.filter(p=>!ids.has(p.id)).map(normalize);try{savePatients([...patients,...added]);patients.push(...added);pendingImport=null;navigate('patients');toast(`${added.length} patient record(s) imported.`);}catch(e){toast(e.message);}}break;
 case 'recover':try{download(localStorage.getItem('nourish-patients-v1')||'',`nourish-recovery-${iso().slice(0,10)}.txt`,'text/plain');}catch(e){toast(e.message);}break;
 case 'archive':modal('Archive this patient?',`<p class="dialog-desc">Move ${esc(current().name)} out of the active list? All plans remain on this device and can be restored in Device & data.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Keep patient</button><button class="btn danger" data-action="confirm-archive">Archive patient</button></div>`);break;
 case 'confirm-archive':{const p=current(),previous=p.archivedAt;p.archivedAt=iso();try{if(storageBlocked)throw Error(storageBlocked);savePatients(patients);selectedId=activePatients()[0]?.id||'demo';navigate('patients');toast('Patient archived. Restore in Device & data.');}catch(e){if(previous===undefined)delete p.archivedAt;else p.archivedAt=previous;toast(e.message);}break;}
 }
});
document.addEventListener('submit',event=>{if(event.target.id!=='patient-form')return;event.preventDefault();const name=$('#patient-name').value.trim();if(!name){$('#dialog-error').textContent='Enter a name or patient identifier.';return;}if(storageBlocked){$('#dialog-error').textContent=storageBlocked;return;}if(event.target.dataset.edit==='true'){const previous=current().name;current().name=name;if(!persist()){current().name=previous;$('#dialog-error').textContent=saveError;return;}}else{const p=normalize({id:crypto.randomUUID(),name,createdAt:iso(),updatedAt:iso(),protocolVersion:1});try{savePatients([...patients,p]);patients.push(p);selectedId=p.id;}catch(e){$('#dialog-error').textContent=e.message;return;}}navigate('planner',0);toast('Patient details saved.');});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='patient-search'){query=el.value;$('#patient-cards').innerHTML=patientCards();return;}if(el.dataset.ddp||el.dataset.ddpPortions){const id=el.dataset.ddp||el.dataset.ddpPortions,f=foodById(id),value=el.value===''?null:Number(el.value),q=el.dataset.ddpPortions&&value!==null?value*f.portionSize:value;current().ddp[id]=q;const pair=$(el.dataset.ddp?`[data-ddp-portions="${id}"]`:`[data-ddp="${id}"]`);if(pair)pair.value=q===null?'':Number((el.dataset.ddp?q/f.portionSize:q).toFixed(6));changed();return;}if(el.dataset.gridFood){const p=current();p.distribution[el.dataset.gridFood]||={};p.distribution[el.dataset.gridFood][el.dataset.gridMeal]=el.value===''?null:Number(el.value);changed();return;}if(!el.dataset.field||el.tagName==='SELECT'||el.type==='checkbox')return;const keys=el.dataset.field.split('.');let obj=current();for(const key of keys.slice(0,-1))obj=obj[key];obj[keys.at(-1)]=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;changed();});
document.addEventListener('change',event=>{const el=event.target;if(!el.dataset.field)return;if(el.tagName==='SELECT'||el.type==='checkbox'){const keys=el.dataset.field.split('.');let obj=current();for(const key of keys.slice(0,-1))obj=obj[key];obj[keys.at(-1)]=el.type==='checkbox'?el.checked:el.value;changed();render();}else if(el.dataset.field.startsWith('protocolMeals.')&&!el.dataset.field.endsWith('.note')){const grid=$('#meal-grid');if(grid)grid.innerHTML=mealGrid(true);}});
$('#import-file').addEventListener('change',async event=>{const f=event.target.files[0];if(!f)return;try{if(f.size>15*1024*1024)throw Error('Maximum backup size is 15 MB.');pendingImport=parseBackup(await f.text());const ids=new Set(patients.map(p=>p.id)),fresh=pendingImport.filter(p=>!ids.has(p.id));modal('Preview patient backup',`<p class="dialog-desc">${pendingImport.length} record(s) found in ${esc(f.name)}.</p><div class="formula-box"><strong>${fresh.length} new record(s) will be added.</strong><br>${pendingImport.length-fresh.length} existing ID(s) skipped. Current records are kept.</div><div class="dialog-actions"><button class="btn" data-action="close-dialog">Cancel</button><button class="btn primary" data-action="confirm-import" ${!fresh.length||storageBlocked?'disabled':''}>Import ${fresh.length} record(s)</button></div>`);}catch(e){toast(e.message);}event.target.value='';});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('storage',event=>{if(event.key==='nourish-patients-v1'){storageBlocked='Records changed in another tab. Reload before editing to avoid overwriting those changes.';render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.mobile-overlay')?.classList.remove('show');syncMenu();}});
matchMedia('(max-width:720px)').addEventListener('change',syncMenu);
render();
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{swReady=true;const el=$('#network-status');if(el)el.innerHTML='<i class="dot"></i>Offline ready';}).catch(()=>{const el=$('#network-status');if(el)el.textContent='Offline cache unavailable';});
